import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [isLogged, setIsLogged] = useState(false);
  const [user, setUser] = useState({ name: 'Dr. Rodrigo', office: 'Rodrigo Advocacia' });
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v8_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [novoProc, setNovoProc] = useState({ cliente: '', valor: '', data: '', area: 'Cível' });

  useEffect(() => {
    localStorage.setItem('juris_v8_data', JSON.stringify(processos));
  }, [processos]);

  const calcularPrazoFinal = (dataInicio) => {
    if (!dataInicio) return '---';
    let data = new Date(dataInicio + 'T00:00:00');
    let dias = 0;
    while (dias < 15) {
      data.setDate(data.getDate() + 1);
      if (data.getDay() !== 0 && data.getDay() !== 6) dias++;
    }
    return data.toLocaleDateString('pt-BR');
  };

  const handleLogin = (e) => {
    e.preventDefault();
    setIsLogged(true);
  };

  if (!isLogged) {
    return (
      <div style={s.loginPage}>
        <div style={s.loginCard}>
          <div style={s.brandIconBig}>J</div>
          <h2 style={{color: COLORS.accent}}>JurisPRO System</h2>
          <p style={{color: COLORS.muted}}>Acesse sua banca jurídica digital</p>
          <form onSubmit={handleLogin} style={{width: '100%', marginTop: '20px'}}>
            <input style={s.input} type="email" placeholder="E-mail profissional" required />
            <input style={s.input} type="password" placeholder="Senha" required />
            <button style={s.btnMain}>ENTRAR NO PAINEL</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div style={s.app}>
      <aside style={s.sidebar} className="no-print">
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'novo')} onClick={() => setTab('novo')}>➕ Novo Caso</div>
          <div style={s.navLink(tab === 'perfil')} onClick={() => setTab('perfil')}>⚙️ Configurações</div>
        </nav>
        <div style={s.userBadge}>
          <div style={s.avatar}>{user.name[4]}</div>
          <div>
            <div style={{fontSize: '12px', fontWeight: 'bold'}}>{user.name}</div>
            <div style={{fontSize: '10px', color: COLORS.gold}}>Premium Cloud</div>
          </div>
        </div>
      </aside>

      <main style={s.content}>
        <header style={s.header} className="no-print">
          <div>
            <h2 style={{margin: 0}}>{user.office}</h2>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>Gestão de Alta Performance [v8.0]</p>
          </div>
          <button style={s.btnExport} onClick={() => window.print()}>📄 EXPORTAR PDF</button>
        </header>

        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Honorários" value={`R$ ${processos.reduce((a,b)=>a+Number(b.valor),0).toLocaleString()}`} color={COLORS.success} />
            <StatCard label="Processos" value={processos.length} color={COLORS.accent} />
            <StatCard label="Status" value="Monitorado" color={COLORS.gold} />

            <div style={{...s.card, gridColumn: 'span 3'}}>
              <h3 style={{marginTop: 0}}>Carteira de Clientes e Prazos</h3>
              <table style={s.table}>
                <thead>
                  <tr>
                    <th style={s.th}>CLIENTE</th>
                    <th style={s.th}>VALOR</th>
                    <th style={s.th}>PRAZO CPC/15</th>
                  </tr>
                </thead>
                <tbody>
                  {processos.map(p => (
                    <tr key={p.id}>
                      <td style={s.td}><strong>{p.cliente}</strong></td>
                      <td style={s.td}>R$ {Number(p.valor).toLocaleString()}</td>
                      <td style={s.td}><span style={s.deadline}>{calcularPrazoFinal(p.data)}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {tab === 'novo' && (
          <div style={{...s.card, maxWidth: '500px', margin: '0 auto'}}>
            <h3>➕ Novo Registro</h3>
            <input style={s.input} placeholder="Cliente" onChange={e => setNovoProc({...novoProc, cliente: e.target.value})} />
            <input style={s.input} type="number" placeholder="Honorários (R$)" onChange={e => setNovoProc({...novoProc, valor: e.target.value})} />
            <input style={s.input} type="date" onChange={e => setNovoProc({...novoProc, data: e.target.value})} />
            <button style={s.btnMain} onClick={() => {
              setProcessos([...processos, {...novoProc, id: Date.now()}]);
              setTab('dashboard');
            }}>SALVAR</button>
          </div>
        )}

        {tab === 'perfil' && (
          <div style={{...s.card, maxWidth: '500px', margin: '0 auto'}}>
            <h3>⚙️ Configurações da Banca</h3>
            <label style={s.label}>Nome do Advogado</label>
            <input style={s.input} value={user.name} onChange={e => setUser({...user, name: e.target.value})} />
            <label style={s.label}>Nome do Escritório</label>
            <input style={s.input} value={user.office} onChange={e => setUser({...user, office: e.target.value})} />
            <button style={s.btnMain} onClick={() => alert("Perfil atualizado!")}>ATUALIZAR DADOS</button>
          </div>
        )}
      </main>
      <style>{`@media print {.no-print {display: none !important;} body {background: white; color: black;}}`}</style>
    </div>
  );
}

const StatCard = ({label, value, color}) => (
  <div style={s.card}>
    <div style={{color: COLORS.muted, fontSize: '11px', fontWeight: 'bold'}}>{label.toUpperCase()}</div>
    <div style={{fontSize: '24px', fontWeight: 'bold', color: color, marginTop: '10px'}}>{value}</div>
  </div>
);

const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: 'Inter, sans-serif' },
  loginPage: { height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: COLORS.bg },
  loginCard: { backgroundColor: COLORS.card, padding: '40px', borderRadius: '24px', textAlign: 'center', width: '350px', border: `1px solid ${COLORS.border}` },
  brandIconBig: { width: '60px', height: '60px', backgroundColor: COLORS.accent, margin: '0 auto 20px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '32px', fontWeight: 'bold', color: 'white' },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '30px 20px' },
  brand: { fontSize: '22px', fontWeight: 'bold', color: COLORS.accent, display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '40px' },
  brandIcon: { width: '30px', height: '30px', backgroundColor: COLORS.accent, borderRadius: '6px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' },
  nav: { flex: 1 },
  navLink: (active) => ({ padding: '14px', borderRadius: '10px', cursor: 'pointer', marginBottom: '8px', color: active ? COLORS.accent : COLORS.muted, backgroundColor: active ? '#38bdf811' : 'transparent', fontSize: '14px' }),
  userBadge: { display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', backgroundColor: '#000', borderRadius: '12px' },
  avatar: { width: '35px', height: '35px', backgroundColor: COLORS.gold, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'black', fontWeight: 'bold' },
  content: { flex: 1, padding: '40px', overflowY: 'auto' },
  header: { display: 'flex', justifyContent: 'space-between', marginBottom: '40px' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' },
  card: { backgroundColor: COLORS.card, padding: '25px', borderRadius: '16px', border: `1px solid ${COLORS.border}` },
  table: { width: '100%', borderCollapse: 'collapse', marginTop: '15px' },
  th: { textAlign: 'left', padding: '12px', color: COLORS.muted, fontSize: '11px', borderBottom: `1px solid ${COLORS.border}` },
  td: { padding: '15px', borderBottom: `1px solid ${COLORS.border}`, fontSize: '13px' },
  deadline: { color: COLORS.danger, fontWeight: 'bold' },
  input: { width: '100%', padding: '12px', backgroundColor: '#000', border: `1px solid ${COLORS.border}`, color: 'white', borderRadius: '8px', marginBottom: '15px' },
  label: { fontSize: '12px', color: COLORS.muted, marginBottom: '5px', display: 'block' },
  btnMain: { width: '100%', padding: '15px', backgroundColor: COLORS.accent, color: '#000', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' },
  btnExport: { padding: '10px 20px', backgroundColor: 'transparent', color: COLORS.accent, border: `1px solid ${COLORS.accent}`, borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }
};
